/**
 * Feeds the panel and the option cards a payload generated by the real backend: the metrics are the
 * output of `multi_option_scoring.score_multi_option` (canned verifier verdicts) and the rows are
 * filtered through `evaluation_service._multi_option_preview` (the capped preview). Regenerate the fixture
 * when either side changes shape.
 */
import { fireEvent, render, screen } from '@testing-library/react';
import { describe, expect, it } from 'vitest';

import fixture from './multiOptionBackendShape.fixture.json';
import MultiOptionMetricsPanel, { MultiOptionRowView, isMultiOptionMetrics, isMultiOptionRow, type MultiOptionMetrics, type MultiOptionRow } from './MultiOptionMetricsPanel';

const METRICS = fixture.metrics as unknown as MultiOptionMetrics;
const ROWS = fixture.predictions_preview as unknown as MultiOptionRow[];

describe('multi-option components against the backend payload shape', () => {
    it('detects the mode and rows', () => {
        expect(isMultiOptionMetrics(METRICS)).toBe(true);
        expect(isMultiOptionMetrics({ scoring_mode: 'remediation' })).toBe(false);
        expect(isMultiOptionRow(ROWS[0])).toBe(true);
        expect(isMultiOptionRow({ scoring_mode: 'structured_plan' })).toBe(false);
    });

    it('the panel shows the headline, the excluded rows and the verifier provenance', () => {
        render(<MultiOptionMetricsPanel metrics={METRICS} provenance="Run #7 · test · result 12" />);
        expect(screen.getByTestId('mo-pass')).toHaveTextContent('50.0%');
        expect(screen.getByTestId('mo-pass')).toHaveTextContent('2 of 4 verified rows');
        expect(screen.getByTestId('mo-option-pass')).toHaveTextContent('75.0%');
        expect(screen.getByTestId('mo-taxonomy')).toHaveTextContent('57.1%');
        expect(screen.getByTestId('mo-agreement')).toHaveTextContent('90.9%');
        expect(screen.getByTestId('mo-verifier-errors')).toHaveTextContent('1 row could not be verified');
        expect(screen.getByTestId('mo-option-failures')).toHaveTextContent('1 option timed out, crashed');
        expect(screen.getByTestId('mo-provenance')).toHaveTextContent('verifier example_option_verifier (revision 3)');
        expect(screen.getByTestId('mo-provenance')).toHaveTextContent('format_a, format_b');
        expect(screen.getByText(/Run #7 · test · result 12/)).toBeInTheDocument();
        expect(screen.getByTestId('mo-format-format_b')).toHaveTextContent('90.9%');
        expect(screen.getByTestId('mo-check-behaviour_changed').querySelector('.mo-bars__fill--w-100')).not.toBeNull();
    });

    it('option cards: strategy, per-format checks, agreement and the out-of-taxonomy chip', () => {
        render(<MultiOptionRowView row={ROWS[0]} />);
        expect(screen.getByTestId('mo-chip-pass')).toHaveTextContent('pass');
        expect(screen.getByTestId('mo-option-0-strategy')).toHaveTextContent('guard-clause');
        expect(screen.getByTestId('mo-option-0-status')).toHaveTextContent('passes');
        expect(screen.getByTestId('mo-option-0-check-format_b-behaviour_preserved')).toHaveTextContent('n/a');
        expect(screen.getByTestId('mo-option-1-agreement')).toHaveTextContent('formats disagree');
        expect(screen.getByTestId('mo-option-1-agreement')).toHaveTextContent('leaves the old branch');
        expect(screen.getByTestId('mo-option-1-status')).toHaveTextContent('fails');
        const outside = screen.getByTestId('mo-option-2-strategy');
        expect(outside).toHaveTextContent('rewrite (not in taxonomy)');
        expect(outside).toHaveClass('is-muted');
        // tabs switch the fix text
        expect(screen.getByTestId('mo-option-0-fix')).toHaveTextContent('--- a/f.py');
        fireEvent.click(screen.getByTestId('mo-option-0-tab-format_b'));
        expect(screen.getByTestId('mo-option-0-fix')).toHaveTextContent('return xs[0] if xs else None');
    });

    it('failed checks show the verifier messages', () => {
        render(<MultiOptionRowView row={ROWS[1]} />);
        expect(screen.getByTestId('mo-chip-pass')).toHaveTextContent('fail');
        expect(screen.getByTestId('mo-option-0-check-format_b-behaviour_changed')).toHaveTextContent('fail');
        expect(screen.getByTestId('mo-option-0-messages')).toHaveTextContent('format_b: the failing input still fails');
    });

    it('a verifier crash on one option fails that option with its reason', () => {
        render(<MultiOptionRowView row={ROWS[1]} />);
        expect(screen.getByTestId('mo-option-2-status')).toHaveTextContent('fails');
        expect(screen.getByTestId('mo-option-2-failure')).toHaveTextContent('the verifier crashed on this option');
        expect(screen.getByTestId('mo-option-2-failure')).toHaveTextContent('exit 3');
        // the fix text is still shown for an option the verifier crashed on
        expect(screen.getByTestId('mo-option-2-fix')).toHaveTextContent('--- a/f.py');
    });

    it('an infrastructure error on the deciding option is shown as not verified, never as a failure', () => {
        render(<MultiOptionRowView row={ROWS[2]} />);
        expect(screen.getByTestId('mo-chip-pass')).toHaveTextContent('not verified');
        expect(screen.getByTestId('mo-row-note')).toHaveTextContent('could not run');
        expect(screen.getByTestId('mo-option-0-status')).toHaveTextContent('unverified');
        expect(screen.getByTestId('mo-option-0-error')).toHaveTextContent('binary not found');
    });

    it('long fixes and long option lists are capped in the preview and say so', () => {
        render(<MultiOptionRowView row={ROWS[4]} />);
        expect(screen.getByTestId('mo-option-0-fix')).toHaveTextContent('(truncated)');
        expect(screen.getByTestId('mo-option-0-fix').textContent!.length).toBeLessThan(1600);
        expect(screen.getByTestId('mo-row-options-truncated')).toHaveTextContent('(truncated)');
        expect(screen.queryByTestId('mo-option-5')).toBeNull();
    });

    it('a malformed row says so', () => {
        render(<MultiOptionRowView row={ROWS[3]} />);
        expect(screen.getByTestId('mo-row-malformed')).toBeInTheDocument();
        expect(screen.getByTestId('mo-chip-count')).toHaveTextContent('0 options');
    });

    it('never carries the verifier payload', () => {
        expect(JSON.stringify(fixture)).not.toContain('verifier_payload');
    });
});
